extends Node3D

@export var target_marker: Node3D
@export var turn_speed_degrees: float = 90.0
@export var move_speed: float = 2.0

func _process(delta: float) -> void:
	if target_marker == null:
		return

	# 1. Girarsi gradualmente verso il bersaglio sull'asse orizzontale Y
	var target_pos: Vector3 = target_marker.global_position
	var dir: Vector3 = target_pos - global_position
	dir.y = 0.0 # Ignoriamo il dislivello per non inclinarci

	if dir.length_squared() > 0.001:
		var target_angle: float = atan2(-dir.x, -dir.z)
		var max_step: float = deg_to_rad(turn_speed_degrees) * delta
		rotation.y = rotate_toward(rotation.y, target_angle, max_step)

	# 2. Avanzare verso la direzione in cui guarda l'oggetto
	var forward: Vector3 = -global_transform.basis.z
	global_position += forward * move_speed * delta

func point_arrow_at(target_position: Vector3) -> void:
	# 3. Puntare all'istante verso un punto preciso (es. l'uscita)
	var distance: float = global_position.distance_to(target_position)
	if distance > 0.1:
		look_at(target_position, Vector3.UP)

