func _run_tests() -> void:
	var main := await instantiate_main_scene()
	if not check("main", main != null, "La scena principale deve caricarsi senza errori"):
		return
	var exit_arrow := find_by_name(main, "ExitArrow") as Node3D
	if not check("arrow", exit_arrow != null, "La scena deve contenere un nodo chiamato ExitArrow"):
		return
	var target := find_by_name(main, "BlockEastTop") as Node3D
	if not check("target", target != null, "La scena deve contenere il nodo BlockEastTop"):
		return

	var initial_pos: Vector3 = exit_arrow.global_position
	await wait_physics_frames(20)

	var new_pos: Vector3 = exit_arrow.global_position
	var moved: bool = initial_pos.distance_to(new_pos) > 0.05
	check("moved", moved, "ExitArrow deve essersi spostato in avanti (posizione iniziale: %s, nuova: %s)" % [str(initial_pos), str(new_pos)])

	var target_dir: Vector3 = (target.global_position - exit_arrow.global_position).normalized()
	var forward: Vector3 = -exit_arrow.global_transform.basis.z.normalized()
	var dot: float = forward.dot(target_dir)
	check("facing", dot > 0.9, "L'asse avanti di ExitArrow (-basis.z) deve puntare verso BlockEastTop (prodotto scalare: %.2f)" % dot)

